import { OpenSearchVersionExtractor } from '../src/OpenSearchVersionExtractor';
import { OpenAPIV3 } from 'openapi-types';

describe('OpenSearchVersionExtractor - Basic Tests', () => {
    describe('process', () => {
        it('should process basic spec', () => {
            const spec: any = {
                openapi: '3.1.0',
                info: { title: 'Test API', version: '1.0.0' },
                paths: {
                    '/test': {
                        get: {
                            responses: {
                                '200': {
                                    description: 'Success',
                                    content: {
                                        'application/json': {
                                            schema: {
                                                $ref: '#/components/schemas/ns___TestSchema'
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                },
                components: {
                    schemas: {
                        'ns___TestSchema': {
                            type: 'object',
                            properties: {
                                oldField: {
                                    type: 'string',
                                    'x-version-added': '2.0.0'
                                },
                                newField: {
                                    type: 'string',
                                    'x-version-added': '3.0.0'
                                }
                            }
                        }
                    }
                }
            };

            const extractor = new OpenSearchVersionExtractor(spec);
            const result = extractor.process('2.5.0');

            // Schema should still exist (keeps ns___ prefix, not renamed by OpenSearchVersionExtractor)
            expect(result.components!.schemas).toBeDefined();
            const schema = result.components!.schemas!['ns___TestSchema'] as OpenAPIV3.SchemaObject;
            expect(schema).toBeDefined();

            // Field added in 2.0.0 should be kept (2.0.0 <= 2.5.0)
            expect(schema.properties).toHaveProperty('oldField');

            // Field added in 3.0.0 should be removed (3.0.0 > 2.5.0)
            expect(schema.properties).not.toHaveProperty('newField');
        });

        it('should handle deprecation', () => {
            const spec: any = {
                openapi: '3.1.0',
                info: { title: 'Test API', version: '1.0.0' },
                paths: {
                    '/current': {
                        get: {
                            responses: {
                                '200': {
                                    description: 'Success',
                                    content: {
                                        'application/json': {
                                            schema: {
                                                $ref: '#/components/schemas/CurrentSchema'
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    },
                    '/deprecated': {
                        get: {
                            responses: {
                                '200': {
                                    description: 'Success',
                                    content: {
                                        'application/json': {
                                            schema: {
                                                $ref: '#/components/schemas/DeprecatedSchema'
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                },
                components: {
                    schemas: {
                        'CurrentSchema': {
                            type: 'object',
                            properties: {
                                field: { type: 'string' }
                            }
                        },
                        'DeprecatedSchema': {
                            type: 'object',
                            'x-version-deprecated': '2.0.0',
                            properties: {
                                field: { type: 'string' }
                            }
                        }
                    }
                }
            };

            const extractor = new OpenSearchVersionExtractor(spec);
            const result = extractor.process('2.5.0');

            expect(result.components!.schemas).toHaveProperty('CurrentSchema');

            expect(result.components!.schemas).not.toHaveProperty('DeprecatedSchema');

            // OpenSearchVersionExtractor removes schemas but not paths
            expect(result.paths).toHaveProperty('/current');
        });

        it('should handle version in paths', () => {
            const spec: any = {
                openapi: '3.1.0',
                info: { title: 'Test API', version: '1.0.0' },
                paths: {
                    '/old-endpoint': {
                        'x-version-deprecated': '2.0.0',
                        get: {
                            responses: {}
                        }
                    },
                    '/new-endpoint': {
                        get: {
                            responses: {}
                        }
                    }
                }
            };

            const extractor = new OpenSearchVersionExtractor(spec);
            const result = extractor.process('2.5.0');

            expect(result.paths).not.toHaveProperty('/old-endpoint');
            expect(result.paths).toHaveProperty('/new-endpoint');
        });

        it('should handle version in operations', () => {
            const spec: any = {
                openapi: '3.1.0',
                info: { title: 'Test API', version: '1.0.0' },
                paths: {
                    '/endpoint': {
                        get: {
                            'x-version-deprecated': '2.0.0',
                            responses: {}
                        },
                        post: {
                            responses: {}
                        }
                    }
                }
            };

            const extractor = new OpenSearchVersionExtractor(spec);
            const result = extractor.process('2.5.0');

            expect(result.paths!['/endpoint']!.get).toBeUndefined();
            expect(result.paths!['/endpoint']!.post).toBeDefined();
        });
    });
});

/**
 * Tests for OpenApiTraverser.
 */

import type { OpenAPIV3 } from 'openapi-types';
import { traverse, traverseSchema } from '../../src/utils/OpenApiTraverser';

describe('OpenApiTraverser', () => {
    const createDocument = (): OpenAPIV3.Document => ({
        openapi: '3.0.0',
        info: { title: 'Test', version: '1.0.0' },
        paths: {},
        components: { schemas: {} }
    });

    describe('traverse', () => {
        it('should call onSchema for component schemas', () => {
            const doc = createDocument();
            doc.components!.schemas!.TestSchema = {
                type: 'object',
                properties: {
                    name: { type: 'string' }
                }
            };

            const onSchema = jest.fn();
            traverse(doc, { onSchema });

            expect(onSchema).toHaveBeenCalledWith(
                doc.components!.schemas!.TestSchema,
                'TestSchema'
            );
        });

        it('should call onSchemaProperty for nested properties', () => {
            const doc = createDocument();
            doc.components!.schemas!.TestSchema = {
                type: 'object',
                properties: {
                    name: { type: 'string' },
                    age: { type: 'integer' }
                }
            };

            const onSchemaProperty = jest.fn();
            traverse(doc, { onSchemaProperty });

            expect(onSchemaProperty).toHaveBeenCalledWith(
                { type: 'string' },
                'name',
                'TestSchema'
            );
            expect(onSchemaProperty).toHaveBeenCalledWith(
                { type: 'integer' },
                'age',
                'TestSchema'
            );
        });

        it('should pass parent schema name to onSchemaProperty', () => {
            const doc = createDocument();
            doc.components!.schemas!.ParentSchema = {
                type: 'object',
                properties: {
                    child: { 
                        type: 'object',
                        properties: {
                            nested: { type: 'string' }
                        }
                    }
                }
            };

            const onSchemaProperty = jest.fn();
            traverse(doc, { onSchemaProperty });

            // Should be called with parent schema name 'ParentSchema'
            const childCall = onSchemaProperty.mock.calls.find(
                call => call[1] === 'child'
            );
            expect(childCall).toBeDefined();
            expect(childCall![2]).toBe('ParentSchema');
        });

        it('should call onResponseSchema for response schemas', () => {
            const doc = createDocument();
            doc.components!.responses = {
                TestResponse: {
                    description: 'Test',
                    content: {
                        'application/json': {
                            schema: {
                                type: 'object',
                                properties: {
                                    result: { type: 'string' }
                                }
                            }
                        }
                    }
                }
            };

            const onResponseSchema = jest.fn();
            traverse(doc, { onResponseSchema });

            expect(onResponseSchema).toHaveBeenCalledWith(
                expect.objectContaining({ type: 'object' }),
                'TestResponse'
            );
        });

        it('should call onRequestSchema for request body schemas', () => {
            const doc = createDocument();
            doc.components!.requestBodies = {
                TestRequest: {
                    content: {
                        'application/json': {
                            schema: {
                                type: 'object',
                                properties: {
                                    data: { type: 'string' }
                                }
                            }
                        }
                    }
                }
            };

            const onRequestSchema = jest.fn();
            traverse(doc, { onRequestSchema });

            expect(onRequestSchema).toHaveBeenCalledWith(
                expect.objectContaining({ type: 'object' }),
                'TestRequest'
            );
        });

        it('should call onParameter for parameters', () => {
            const doc = createDocument();
            doc.components!.parameters = {
                TestParam: {
                    name: 'test',
                    in: 'query',
                    schema: { type: 'string' }
                }
            };

            const onParameter = jest.fn();
            traverse(doc, { onParameter });

            expect(onParameter).toHaveBeenCalledWith(
                expect.objectContaining({ name: 'test' }),
                'TestParam'
            );
        });

        it('should skip $ref objects', () => {
            const doc = createDocument();
            doc.components!.schemas!.RefSchema = {
                $ref: '#/components/schemas/OtherSchema'
            };

            const onSchemaProperty = jest.fn();
            traverse(doc, { onSchemaProperty });

            // Should not traverse into $ref objects
            expect(onSchemaProperty).not.toHaveBeenCalled();
        });

        it('should handle empty components', () => {
            const doc: OpenAPIV3.Document = {
                openapi: '3.0.0',
                info: { title: 'Test', version: '1.0.0' },
                paths: {}
            };

            const onSchema = jest.fn();
            expect(() => traverse(doc, { onSchema })).not.toThrow();
            expect(onSchema).not.toHaveBeenCalled();
        });
    });

    describe('traverseSchema', () => {
        it('should traverse array items', () => {
            const schema: OpenAPIV3.SchemaObject = {
                type: 'array',
                items: {
                    type: 'object',
                    properties: {
                        name: { type: 'string' }
                    }
                }
            };

            const onSchemaProperty = jest.fn();
            traverseSchema(schema, { onSchemaProperty });

            // Should be called for items
            expect(onSchemaProperty).toHaveBeenCalledWith(
                expect.objectContaining({ type: 'object' }),
                'items',
                undefined
            );

            // Should also be called for nested properties
            expect(onSchemaProperty).toHaveBeenCalledWith(
                { type: 'string' },
                'name',
                undefined
            );
        });

        it('should traverse array items with parent schema name', () => {
            const schema: OpenAPIV3.SchemaObject = {
                type: 'array',
                items: {
                    type: 'string'
                }
            };

            const onSchemaProperty = jest.fn();
            traverseSchema(schema, { onSchemaProperty }, 'ParentSchema');

            expect(onSchemaProperty).toHaveBeenCalledWith(
                { type: 'string' },
                'items',
                'ParentSchema'
            );
        });

        it('should traverse additionalProperties', () => {
            const schema: OpenAPIV3.SchemaObject = {
                type: 'object',
                additionalProperties: {
                    type: 'string'
                }
            };

            const onSchemaProperty = jest.fn();
            traverseSchema(schema, { onSchemaProperty });

            // additionalProperties are traversed but not passed to onSchemaProperty
            // (they don't have a property name)
            expect(onSchemaProperty).not.toHaveBeenCalled();
        });

        it('should traverse allOf schemas', () => {
            const schema: OpenAPIV3.SchemaObject = {
                allOf: [
                    { type: 'object', properties: { a: { type: 'string' } } },
                    { type: 'object', properties: { b: { type: 'number' } } }
                ]
            };

            const onSchema = jest.fn();
            const onSchemaProperty = jest.fn();
            traverseSchema(schema, { onSchema, onSchemaProperty });

            expect(onSchema).toHaveBeenCalledTimes(2);
            expect(onSchemaProperty).toHaveBeenCalledWith(
                { type: 'string' },
                'a',
                undefined
            );
            expect(onSchemaProperty).toHaveBeenCalledWith(
                { type: 'number' },
                'b',
                undefined
            );
        });

        it('should traverse anyOf schemas', () => {
            const schema: OpenAPIV3.SchemaObject = {
                anyOf: [
                    { type: 'string' },
                    { type: 'number' }
                ]
            };

            const onSchema = jest.fn();
            traverseSchema(schema, { onSchema });

            expect(onSchema).toHaveBeenCalledTimes(2);
        });

        it('should traverse oneOf schemas', () => {
            const schema: OpenAPIV3.SchemaObject = {
                oneOf: [
                    { type: 'string' },
                    { type: 'number' }
                ]
            };

            const onSchema = jest.fn();
            traverseSchema(schema, { onSchema });

            expect(onSchema).toHaveBeenCalledTimes(2);
        });

        it('should skip $ref in composed schemas', () => {
            const schema: OpenAPIV3.SchemaObject = {
                allOf: [
                    { $ref: '#/components/schemas/Base' },
                    { type: 'object', properties: { extra: { type: 'string' } } }
                ]
            };

            const onSchema = jest.fn();
            traverseSchema(schema, { onSchema });

            // Should only be called for the non-$ref item
            expect(onSchema).toHaveBeenCalledTimes(1);
        });

        it('should handle deeply nested schemas', () => {
            const schema: OpenAPIV3.SchemaObject = {
                type: 'object',
                properties: {
                    level1: {
                        type: 'object',
                        properties: {
                            level2: {
                                type: 'object',
                                properties: {
                                    level3: { type: 'string' }
                                }
                            }
                        }
                    }
                }
            };

            const onSchemaProperty = jest.fn();
            traverseSchema(schema, { onSchemaProperty });

            // Should be called for all levels
            expect(onSchemaProperty).toHaveBeenCalledWith(
                expect.objectContaining({ type: 'object' }),
                'level1',
                undefined
            );
            expect(onSchemaProperty).toHaveBeenCalledWith(
                expect.objectContaining({ type: 'object' }),
                'level2',
                undefined
            );
            expect(onSchemaProperty).toHaveBeenCalledWith(
                { type: 'string' },
                'level3',
                undefined
            );
        });

        it('should handle empty schema', () => {
            const onSchemaProperty = jest.fn();

            // @ts-ignore - testing runtime behavior
            traverseSchema(null, { onSchemaProperty });

            expect(onSchemaProperty).not.toHaveBeenCalled();
        });
    });
});

name: Backward Compatible Report

on:
  workflow_call:
    inputs:
      opensearch_version:
        description: 'OpenSearch version. Leave empty to fetch latest.'
        required: false
        type: string
      spec_artifact_name:
        description: 'Name of the uploaded artifact containing opensearch-openapi.yaml'
        required: false
        type: string
        default: 'openapi-spec'
    outputs:
      report:
        description: 'The compatibility report in markdown format'
        value: ${{ jobs.generate-report.outputs.report }}

  workflow_dispatch:
    inputs:
      opensearch_version:
        description: 'OpenSearch version. Leave empty to fetch latest.'
        required: false
        type: string

jobs:
  generate-report:
    runs-on: ubuntu-latest
    outputs:
      report: ${{ steps.merge_report.outputs.report }}
    steps:
      - name: Checkout Repository
        uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4
        with:
          repository: ${{ github.repository_owner }}/opensearch-protobufs
          ref: main

      - name: Setup Node.js
        uses: actions/setup-node@3235b876344d2a9aa001b8d1453c930bba69e610 # v3
        with:
          node-version: 20

      - name: Setup Java
        uses: actions/setup-java@17f84c3641ba7b8f6deff6309fc4c864478f5d62 # v3
        with:
          distribution: temurin
          java-version: 17

      - name: Download OpenAPI spec artifact
        if: ${{ inputs.spec_artifact_name != '' }}
        uses: actions/download-artifact@d3f86a106a0bac45b974a628896c90dbdf5c8093 # v4
        with:
          name: ${{ inputs.spec_artifact_name }}
          path: .

      - name: Get Latest OpenSearch Core Version
        id: get_opensearch_version
        uses: actions/github-script@d7906e4ad0b1822421a7e6a35d5ca353c962f410 # v6
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            // Check if version was provided as input
            const inputVersion = "${{ inputs.opensearch_version }}";
            if (inputVersion && inputVersion.trim() !== "") {
              core.setOutput("version", inputVersion.trim());
              console.log("Using provided OpenSearch version: " + inputVersion.trim());
              return;
            }

            // Otherwise fetch version from buildSrc/version.properties on main branch
            try {
              const response = await github.request(
                'GET /repos/{owner}/{repo}/contents/{path}',
                {
                  owner: 'opensearch-project',
                  repo: 'OpenSearch',
                  path: 'buildSrc/version.properties',
                  ref: 'main'
                }
              );

              // Decode the file content
              const content = Buffer.from(response.data.content, 'base64').toString('utf-8');

              // Extract opensearch version (e.g., "opensearch = 3.4.0")
              const match = content.match(/opensearch\s*=\s*([^\s]+)/);

              if (match && match[1]) {
                const version = match[1].trim();
                core.setOutput("version", version);
                console.log("Fetched OpenSearch version from source: " + version);
              } else {
                core.setFailed("Could not find opensearch version in version.properties");
              }
            } catch (error) {
              core.setFailed("Could not fetch OpenSearch version: " + error.message);
            }

      - name: Run Proto Conversion
        env:
          OPENSEARCH_VERSION: ${{ steps.get_opensearch_version.outputs.version }}
        run: npm ci && npm run preprocessing -- --opensearch-version "$OPENSEARCH_VERSION"

      - name: Convert protobuf
        env:
          OPENAPI_GENERATOR_VERSION: 7.19.0
        run: |
          npx --yes @openapitools/openapi-generator-cli generate \
            -c tools/proto-convert/src/config/protobuf-generator-config.yaml

      - name: Check for auto-pr-branch and use its protos if exists
        run: |
          # Check if auto-pr-branch exists
          if git ls-remote --exit-code --heads origin auto-pr-branch > /dev/null 2>&1; then
            echo "Found auto-pr-branch, using its proto files for comparison"
            git fetch origin auto-pr-branch
            git checkout origin/auto-pr-branch -- protos/schemas/
          else
            echo "auto-pr-branch not found, using main branch proto files"
          fi

      - name: Post Process Protobuf (dry-run for report)
        id: merge_report
        run: |
          npm run postprocessing:dry-run
          REPORT_PATH="/tmp/merge-report.md"

          echo "=== Compatibility Report ==="
          cat "$REPORT_PATH"
          echo "============================="

          REPORT=$(cat "$REPORT_PATH")
          echo "report<<EOF" >> $GITHUB_OUTPUT
          echo "$REPORT" >> $GITHUB_OUTPUT
          echo "EOF" >> $GITHUB_OUTPUT

import _ from 'lodash';
import * as semver from 'semver';
import logger from './utils/logger';
import { deleteMatchingKeys, remove_unused } from './utils/helper';
import type { OpenAPIV3 } from 'openapi-types';

/**
 * x-version-added: Removes fields if the added version > target version.
 * x-version-deprecated: Removes fields if deprecated version <= target version.
 * x-version-removed: Removes fields if removed version <= target version.
 */
export class OpenSearchVersionExtractor {
  private _spec: OpenAPIV3.Document;
  private _target_version: string;

  constructor(spec: OpenAPIV3.Document) {
    this._spec = spec;
    this._target_version = '';
  }


  process(currentVersion: string): OpenAPIV3.Document {
    const coerced = semver.coerce(currentVersion);
    this._target_version = coerced?.toString() || currentVersion;
    logger.info(`Processing version constraints for OpenSearch ${this._target_version} ...`);

    deleteMatchingKeys(this._spec, this.#exclude_per_semver.bind(this));
    remove_unused(this._spec);

    logger.info('Version processing complete');
    return this._spec;
  }

  #exclude_per_semver(obj: any): boolean {
    if (this._target_version == undefined) return false

    const x_version_added = semver.coerce(obj['x-version-added'] as string)
    const x_version_deprecated = semver.coerce(obj['x-version-deprecated'] as string)
    const x_version_removed = semver.coerce(obj['x-version-removed'] as string)

    if (x_version_added !== null) {
      if (semver.gt(x_version_added, this._target_version)) {
          return true
      }
    }


    if (x_version_deprecated !== null) {
      if (semver.lte(x_version_deprecated, this._target_version)) {
          return true
      }
    }

    // TODO: Uncomment this when figure out https://github.com/opensearch-project/opensearch-api-specification/blob/61777cdbe5bc32204640e6e236daf7cf71aa871d/spec/schemas/_common.yaml#L12
    // if (x_version_removed !== null) {
    //   if (semver.lte(x_version_removed, this._target_version)) {
    //       return true
    //   }
    // }

    return false
  }
}

import { OpenAPIV3 } from 'openapi-types';

export type SchemaVisitorSet = {
    onSchema?: (schema: OpenAPIV3.SchemaObject | OpenAPIV3.ReferenceObject, name: string) => void;
    onResponseSchema?: (schema: OpenAPIV3.SchemaObject, name: string) => void;
    onRequestSchema?: (schema: OpenAPIV3.SchemaObject, name: string) => void;
    onParameter?: (param: OpenAPIV3.ParameterObject, name: string) => void;
    onSchemaProperty?: (schema: OpenAPIV3.SchemaObject, propertyName: string, parentSchemaName?: string) => void;
};

/**
 * Traverse OpenAPI spec components and invoke visitors on each type.
 */
export function traverse(
    spec: OpenAPIV3.Document,
    visitors: SchemaVisitorSet
): void {
    const components = spec.components;
    if (!components) return;

    // schemas
    if (components.schemas) {
        for (const schemaName in components.schemas) {
            const schema = components.schemas[schemaName];
            visitors.onSchema?.(schema, schemaName);
            if (!('$ref' in schema)) {
                traverseSchema(schema, visitors, schemaName);
            }
        }
    }

    // responses
    if (components.responses) {
        for (const responseName in components.responses) {
            const response = components.responses[responseName];
            if (!('$ref' in response) && response.content?.['application/json']?.schema) {
                const schema = response.content['application/json'].schema;
                if (!('$ref' in schema)) {
                    visitors.onResponseSchema?.(schema, responseName);
                    traverseSchema(schema, visitors);
                }
            }
        }
    }

    // requestBodies
    if (components.requestBodies) {
        for (const requestName in components.requestBodies) {
            const request = components.requestBodies[requestName];
            if (!('$ref' in request)) {
                for (const contentType in request.content || {}) {
                    const content = (request.content as any)?.[contentType];
                    if (content?.schema && !('$ref' in content.schema)) {
                        const schema = content.schema;
                        visitors.onRequestSchema?.(schema, requestName);
                        traverseSchema(schema as OpenAPIV3.SchemaObject, visitors);
                    }
                }
            }
        }
    }

    // parameters
    if (components.parameters) {
        for (const paramName in components.parameters) {
            const param = components.parameters[paramName];
            if (!('$ref' in param)) {
                visitors.onParameter?.(param, paramName);
                if (param.schema && !('$ref' in param.schema)) {
                    traverseSchema(param.schema, visitors);
                }
            }
        }
    }
}

/**
 * Recursively traverses a schema and applies onSchemaProperty to all properties found.
 */
export function traverseSchema(
    schema: OpenAPIV3.SchemaObject,
    visitors: SchemaVisitorSet,
    parentSchemaName?: string
): void {
    if (!schema) return;

    // Visit direct properties
    if (schema.properties) {
        for (const propName in schema.properties) {
            const propSchema = schema.properties[propName];
            if (!('$ref' in propSchema)) {
                visitors.onSchemaProperty?.(propSchema, propName, parentSchemaName);
                traverseSchema(propSchema, visitors, parentSchemaName); // recurse into nested properties
            }
        }
    }

    // Visit items (for array types)
    if (schema.type === 'array' && schema.items && typeof schema.items === 'object' && !('$ref' in schema.items)) {
        const itemsSchema = schema.items as OpenAPIV3.SchemaObject;
        visitors.onSchemaProperty?.(itemsSchema, 'items', parentSchemaName);
        traverseSchema(itemsSchema, visitors, parentSchemaName);
    }

    // Visit additionalProperties
    if (schema.additionalProperties && typeof schema.additionalProperties === 'object' && !('$ref' in schema.additionalProperties)
    ) {
        traverseSchema(schema.additionalProperties as OpenAPIV3.SchemaObject, visitors, parentSchemaName);
    }

    // Visit composed schemas
    const composedKeys = ['allOf', 'anyOf', 'oneOf'] as const;
    for (const key of composedKeys) {
        const subschemas = schema[key];
        if (Array.isArray(subschemas)) {
            for (const sub of subschemas) {
                if (!('$ref' in sub)) {
                    visitors.onSchema?.(sub, `${key}`);
                    traverseSchema(sub, visitors, parentSchemaName);
                }
            }
        }
    }
}

import * as fs from "fs";
