describe('GlobalParameterConsolidator', () => {
    describe('consolidate', () => {
        it('should consolidate global parameters and replace in operations', () => {
            const spec: OpenAPIV3.Document = {
                openapi: '3.1.0',
                info: { title: 'Test API', version: '1.0.0' },
                paths: {
                    '/test': {
